// 1. Bezpieczny odczyt danych z OpenAI (obsługa obiektu i tekstu)
const rawContent = $json.output?.[0]?.content?.[0]?.text;
let parsedAi = {};

if (typeof rawContent === 'object' && rawContent !== null) {
  // n8n sparsował już JSON automatycznie do obiektu
  parsedAi = rawContent;
} else if (typeof rawContent === 'string') {
  // Dane przyszły jako czysty ciąg tekstowy JSON
  try {
    parsedAi = JSON.parse(rawContent);
  } catch (e) {
    parsedAi = {};
  }
} else {
  parsedAi = $json;
}

// 2. Baza wiedzy firmy (Procedury i zasady dla BOK)
const knowledgeBase = {
  "DOSTAWA_I_LOGISTYKA": `
    - Standardowy czas dostawy wynosi 2-3 dni robocze od momentu opłacenia zamówienia.
    - Jeśli od wysyłki minęło więcej niż 4 dni, przeproś klienta i poinformuj, że Dział Logistyki złożył już ponaglenie u przewoźnika.
    - Zaoferuj kod rabatowy -10% na kolejne zakupy (kod: PRZEPRASZAM10) za opóźnienie.
  `,
  "REKLAMACJA_I_ZWROT": `
    - Klient ma 14 dni na zwrot towaru bez podania przyczyny.
    - Formularz zwrotu znajduje się pod adresem: https://naszsklep.pl/zwroty
    - W przypadku uszkodzonej paczki prosimy o przesłanie zdjęć uszkodzenia.
    - Pieniądze zwracamy tą samą metodą płatności w ciągu 5 dni roboczych od odbioru paczki w magazynie.
  `,
  "PYTANIE_O_PRODUKT": `
    - Wszystkie specyfikacje techniczne znajdują się w zakładce "Opis produktu" na naszej stronie.
    - Jeśli klient pyta o dostępność rozmiaru/koloru, poinformuj o możliwości zapisania się na powiadomienie o dostępności.
  `,
  "INNE": `
    - Podziękuj za wiadomość i poinformuj, że sprawa została przekazana do odpowiedniego działu.
    - Odpowiemy najszybciej jak to możliwe (maksymalnie do 24 godzin).
  `
};

// 3. Pobranie odpowiedniej polityki na podstawie kategorii z AI
const category = parsedAi.category || "INNE";
const selectedPolicy = knowledgeBase[category] || knowledgeBase["INNE"];

// 4. Pobranie pierwotnych danych z Gmaila
const gmailData = $node["Gmail Trigger"].json;

return {
  json: {
    // Dane z Gmaila
    threadId: gmailData.threadId,
    emailMessageId: gmailData.id,
    customerEmail: gmailData.From,
    emailSubject: gmailData.Subject,
    emailBody: gmailData.snippet,

    // Analityka AI
    category: category,
    sentiment_score: parsedAi.sentiment_score ?? 3,
    urgency: parsedAi.urgency || "MEDIUM",
    customer_name: parsedAi.customer_name || "Szanowny Kliencie",
    order_id: parsedAi.order_id || null,
    issue_summary: parsedAi.issue_summary || "",

    // Dopasowana procedura biznesowa
    company_policy: selectedPolicy.trim()
  }
};

